// 3. wrapper yang mengecek status
async function ambilJSON(path) {
  const r = await fetch(BASE + path);
  if (!r.ok) {
    const body = await r.json().catch(() => ({}));
    throw new Error(`HTTP ${r.status}: ${body.error ?? r.statusText}`);
  }
  return r.json();
}
